#!/usr/bin/env python3
"""
Guarded patch: switch Mining background from a stretched Crop-to-fill
image to TRUE tiling (ImageShader + TileMode.Repeated). This decouples
icon size from screen size, which is what was actually causing the
"way too big" problem - the previous version stretched one image to
cover the whole screen instead of repeating it at a fixed size.

Also swaps in the new, denser pattern image (mining_bg2 source).
"""
import os
import base64

REPO_ROOT = "."
DRAWABLE_PATH = os.path.join(REPO_ROOT, "app/src/main/res/drawable/bg_mining_pickaxes.webp")
PATTERN_BG_PATH = os.path.join(REPO_ROOT, "app/src/main/kotlin/com/yourname/idlerpg/PatternBackground.kt")

IMAGE_B64 = """"""

# --- 1. Overwrite the drawable with the new, denser pattern image ---
os.makedirs(os.path.dirname(DRAWABLE_PATH), exist_ok=True)
image_bytes = base64.b64decode(IMAGE_B64)
with open(DRAWABLE_PATH, "wb") as f:
    f.write(image_bytes)
print(f"WROTE: {DRAWABLE_PATH} ({len(image_bytes)} bytes)")

# --- 2. Patch PatternBackground.kt ---
with open(PATTERN_BG_PATH, "r", encoding="utf-8") as f:
    content = f.read()


def guarded_replace(content, old, new, marker):
    if marker in content:
        print(f"SKIP (already applied): {marker[:50]}")
        return content
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly 1 match, found {count}.\n--- old_str ---\n{old}\n--- end ---")
    print(f"PATCHED: {marker[:50]}")
    return content.replace(old, new)


# 2a. Add the new imports needed for tiling (leaving the old paint/
#     ContentScale/painterResource imports in place - unused imports are
#     harmless warnings in Kotlin, not errors, and removing them risks a
#     fragile match against the prior patch's exact text).
old_imports = "import com.yourname.idlerpg.R\n"
new_imports = (
    "import androidx.compose.ui.graphics.ImageShader\n"
    "import androidx.compose.ui.graphics.ShaderBrush\n"
    "import androidx.compose.ui.graphics.TileMode\n"
    "import androidx.compose.ui.res.imageResource\n"
    "import com.yourname.idlerpg.R\n"
)
content = guarded_replace(
    content, old_imports, new_imports,
    marker="import androidx.compose.ui.graphics.ImageShader",
)

# 2b. Replace the Crop-to-fill painter version with true tiling
old_fn = (
    "// Real generated image asset (res/drawable/bg_mining_pickaxes.webp) - a\n"
    "// tessellated angled-pickaxe wallpaper pattern - painted to fill the\n"
    "// screen. Replaces the earlier procedural-Canvas attempt.\n"
    "@Composable\n"
    "fun Modifier.miningThemedBackground(): Modifier {\n"
    "    val painter = painterResource(id = R.drawable.bg_mining_pickaxes)\n"
    "    return this.paint(painter, contentScale = ContentScale.Crop)\n"
    "}\n"
)
new_fn = (
    "// Real generated image asset (res/drawable/bg_mining_pickaxes.webp) - a\n"
    "// tessellated angled-pickaxe wallpaper pattern, TRUE-TILED via\n"
    "// ImageShader/TileMode.Repeated so icon size stays fixed regardless of\n"
    "// screen size (Crop-to-fill previously stretched one copy to cover the\n"
    "// whole screen, which is what made icons look oversized).\n"
    "@Composable\n"
    "fun Modifier.miningThemedBackground(): Modifier {\n"
    "    val imageBitmap = imageResource(id = R.drawable.bg_mining_pickaxes)\n"
    "    return this.drawBehind {\n"
    "        drawRect(brush = ShaderBrush(ImageShader(imageBitmap, TileMode.Repeated, TileMode.Repeated)))\n"
    "    }\n"
    "}\n"
)
content = guarded_replace(
    content, old_fn, new_fn,
    marker="TRUE-TILED via\n// ImageShader/TileMode.Repeated",
)

with open(PATTERN_BG_PATH, "w", encoding="utf-8") as f:
    f.write(content)

print("\nDone.")
